/**
 * The shape of src/data/levels.json, which is generated by tools/gen_levels.py
 * and never edited by hand. Python owns every number in this lesson; this file
 * is the contract the UI reads it through.
 */

export type Outcome = 'hit' | 'fill' | 'evict'

export type Policy = 'fifo' | 'lru' | 'lfu' | 'clock' | 'opt'

/** One tick of the tape under some reference policy. */
export interface Step {
  /** 1-based position on the tape. */
  step: number
  page: number
  outcome: Outcome
  /** The frame index holding `page` after this request. */
  slot: number
  /** The page thrown out, if any. */
  victim: number | null
  /** Frame contents after this request; `null` is an empty slot. */
  frames: (number | null)[]
  /** Use bits after this request. Present on clock traces only. */
  bits?: number[]
  /**
   * 1-based tape position where `victim` is next requested, or `null` if it
   * never is. Present on OPT evictions only — screen 8 draws this.
   */
  victim_next_use?: number | null
}

export interface Scores {
  fifo: number
  lru: number
  /** Least frequently used: the 'I counted how often' answer on screen 5. */
  lfu: number
  clock: number
  opt: number
  /** Clock that rescans from slot 0 every time: the learner who clears bits but keeps no state. */
  clockNoHand: number
  /** "When every bit is 1, clear them all": the other natural first attempt. */
  clearAll: number
  /** Mean faults of a uniformly random evictor — the "mostly guessing" row. */
  randomAvg: number
}

/**
 * The first eviction on a tape where the three past-looking signals disagree.
 *
 * Screen 7 replays this fork and only then reveals `nextUse`. The numbers are
 * sim.first_signal_fork's, not the interface's: which page each rule points at
 * is exactly the kind of figure the front end must never re-derive.
 */
export interface Fork {
  /** 1-based tape position of the eviction. */
  step: number
  /** The page being requested when memory was full. */
  request: number
  /** Resident pages at that moment. */
  mem: number[]
  /** The page each signal would evict. */
  fifo: number
  lru: number
  lfu: number
  /** Page -> 1-based step where it is next requested, or null if never again. */
  nextUse: Record<string, number | null>
}

export interface Level {
  name: 'l1' | 'l2' | 'l3'
  title: string
  ref: number[]
  frames: number
  pages: number[]
  length: number
  scores: Scores
  traces: Partial<Record<Policy, Step[]>>
  /** Null on tapes whose first eviction is not diagnostic. */
  fork: Fork | null
}

export interface BeladyRun {
  small: { frames: number; faults: number; steps: Step[] }
  big: { frames: number; faults: number; steps: Step[] }
  /** 1-based steps where the small memory holds a page the big one has dropped. */
  leakSteps: number[]
}

export interface LevelData {
  generatedBy: string
  levels: Record<'l1' | 'l2' | 'l3', Level>
  belady: {
    ref: number[]
    pages: number[]
    length: number
    runs: Record<Policy, BeladyRun>
  }
}

/**
 * What the machine's face displays. The rest of the app knows these six words
 * and nothing about what is drawn for them — see setMachineState.
 */
export type MachineState =
  | 'neutral'
  | 'approval'
  | 'correction'
  | 'smug'
  | 'apologetic'
  | 'withholding'

/**
 * Screen 5: what the learner says they were doing, held to it on screen 6.
 *
 * Four options, four different measurable things: time since last use, time in
 * memory, total number of uses, and nothing. An earlier set had two options
 * that pointed at the same page ("hadn't touched in a while" and "could
 * remember least about") and one that was ambiguous between two policies
 * ("sitting there longest" reads as both arrival order and idle time), which
 * meant screen 6 could hold the learner to a rule they had not meant.
 */
export type DeclaredRule = 'lru' | 'fifo' | 'lfu' | 'random'
